fn mutual_friends(a: &Set[Str], b: &Set[Str]) -> Set[Str] {
  return a.intersection(b);
}

fn all_friends(a: &Set[Str], b: &Set[Str]) -> Set[Str] {
  return a.union(b);
}

fn only_a_friends(a: &Set[Str], b: &Set[Str]) -> Set[Str] {
  return a.difference(b);
}

fn main() -> Int {
  let a = Set[Str]();
  a.insert("Alice"); a.insert("Bob"); a.insert("Carol");
  let b = Set[Str]();
  b.insert("Bob"); b.insert("Carol"); b.insert("Dave");
  let mutual = mutual_friends(&a, &b);
  return mutual.len();
}
